args.content:
/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
    line-height: 1.6;
    color: #333;
    background-color: #f9f5f0;
}

/* Navigation */
.navbar {
    background-color: #8b4513;
    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    position: sticky;
    top: 0;
    z-index: 100;
}

.logo {
    color: #fff;
    font-size: 1.5rem;
    font-weight: bold;
    font-family: Georgia, serif;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-links a {
    color: #fff;
    text-decoration: none;
    font-size: 1rem;
    transition: opacity 0.3s;
}

.nav-links a:hover {
    opacity: 0.8;
}

/* Hero Section */
.hero {
    background: linear-gradient(rgba(139, 69, 19, 0.8), rgba(101, 67, 33, 0.8)),
                url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text x="50%" y="50%" font-size="20" text-anchor="middle" fill="%23d4a574">🥐</text></svg>');
    background-size: cover;
    background-position: center;
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 2rem;
}

.hero-content {
    color: #fff;
    max-width: 600px;
}

.hero h1 {
    font-size: 3rem;
    font-family: Georgia, serif;
    margin-bottom: 1rem;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.hero .tagline {
    font-size: 1.5rem;
    font-style: italic;
    margin-bottom: 0.5rem;
}

.hero .subtitle {
    font-size: 1.1rem;
    opacity: 0.9;
}

/* Menu Section */
.menu {
    padding: 4rem 2rem;
    background-color: #fff;
}

.menu h2 {
    text-align: center;
    font-size: 2.5rem;
    font-family: Georgia, serif;
    color: #8b4513;
    margin-bottom: 2rem;
}

.menu-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.5rem;
    max-width: 1200px;
    margin: 0 auto;
}

.menu-item {
    background-color: #f9f5f0;
    padding: 1.5rem;
    border-radius: 8px;
    text-align: center;
    border: 1px solid #e0d0c0;
    transition: transform 0.3s, box-shadow 0.3s;
}

.menu-item:hover {
    transform: translateY(-5px);
    box-shadow: 0 5px 15px rgba(0,0,0,0.1);
}

.item-name {
    font-size: 1.2rem;
    font-weight: 600;
    color: #5c3a1e;
    margin-bottom: 0.5rem;
}

.item-price {
    font-size: 1.3rem;
    font-weight: bold;
    color: #8b4513;
}

/* Hours Section */
.horaires {
    padding: 4rem 2rem;
    background-color: #8b4513;
    color: #fff;
}

.horaires h2 {
    text-align: center;
    font-size: 2.5rem;
    font-family: Georgia, serif;
    margin-bottom: 2rem;
}

.hours-container {
    max-width: 600px;
    margin: 0 auto;
}

.hours-item {
    display: flex;
    justify-content: space-between;
    padding: 1rem;
    background-color: rgba(255,255,255,0.1);
    margin-bottom: 0.5rem;
    border-radius: 5px;
}

.day {
    font-weight: bold;
}

.time {
    font-family: monospace;
    font-size: 1.1rem;
}

/* Contact Section */
.contact {
    padding: 4rem 2rem;
    background-color: #f9f5f0;
}

.contact h2 {
    text-align: center;
    font-size: 2.5rem;
    font-family: Georgia, serif;
    color: #8b4513;
    margin-bottom: 2rem;
}

.contact-form {
    max-width: 500px;
    margin: 0 auto;
}

.form-group {
    margin-bottom: 1.5rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: 600;
    color: #5c3a1e;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.8rem;
    border: 2px solid #e0d0c0;
    border-radius: 5px;
    font-size: 1rem;
    background-color: #fff;
    transition: border-color 0.3s;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #8b4513;
}

.submit-btn {
    width: 100%;
    padding: 1rem;
    background-color: #8b4513;
    color: #fff;
    border: none;
    border-radius: 5px;
    font-size: 1.1rem;
    font-weight: bold;
    cursor: pointer;
    transition: background-color 0.3s;
}

.submit-btn:hover {
    background-color: #6b3612;
}

.submit-btn:active {
    transform: scale(0.98);
}

.thank-you-message {
    text-align: center;
    padding: 2rem;
    background-color: #d4edda;
    border: 2px solid #c3e6cb;
    border-radius: 8px;
    margin-top: 1rem;
    color: #155724;
}

/* Footer */
footer {
    background-color: #333;
    color: #fff;
    text-align: center;
    padding: 2rem;
}

footer p {
    margin-bottom: 0.5rem;
}

/* Responsive Design */
@media (max-width: 768px) {
    .navbar {
        flex-direction: column;
        gap: 1rem;
    }

    .nav-links {
        gap: 1rem;
    }

    .hero {
        min-height: 300px;
        padding: 1.5rem;
    }

    .hero h1 {
        font-size: 2rem;
    }

    .hero .tagline {
        font-size: 1.2rem;
    }

    .menu {
        padding: 2rem 1rem;
    }

    .menu h2 {
        font-size: 2rem;
    }

    .menu-grid {
        grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
        gap: 1rem;
    }

    .menu-item {
        padding: 1rem;
    }

    .item-name {
        font-size: 1rem;
    }

    .item-price {
        font-size: 1.1rem;
    }

    .horaires {
        padding: 2rem 1rem;
    }

    .horaires h2 {
        font-size: 2rem;
    }

    .hours-item {
        flex-direction: column;
        text-align: center;
        gap: 0.25rem;
    }

    .contact {
        padding: 2rem 1rem;
    }

    .contact h2 {
        font-size: 2rem;
    }

    .contact-form {
        max-width: 100%;
    }
}

@media (max-width: 480px) {
    .navbar {
        padding: 0.75rem 1rem;
    }

    .logo {
        font-size: 1.2rem;
    }

    .nav-links {
        gap: 0.75rem;
    }

    .nav-links a {
        font-size: 0.9rem;
    }

    .hero h1 {
        font-size: 1.75rem;
    }

    .hero .tagline {
        font-size: 1rem;
    }

    .menu-grid {
        grid-template-columns: 1fr;
    }
}

document.addEventListener('DOMContentLoaded', function() {
    const contactForm = document.getElementById('contactForm');
    const thankYouMessage = document.getElementById('thankYouMessage');

    contactForm.addEventListener('submit', function(e) {
        e.preventDefault();

        // Get form data
        const formData = {
            name: document.getElementById('name').value.trim(),
            email: document.getElementById('email').value.trim(),
            message: document.getElementById('message').value.trim()
        };

        // Simple validation
        if (formData.name.length === 0) {
            alert('Veuillez entrer votre nom.');
            return;
        }

        if (formData.email.length === 0) {
            alert('Veuillez entrer votre email.');
            return;
        }

        if (formData.message.length === 0) {
            alert('Veuillez entrer un message.');
            return;
        }

        // Simple email validation
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(formData.email)) {
            alert('Veuillez entrer un email valide.');
            return;
        }

        // Simulate form submission
        const submitBtn = contactForm.querySelector('.submit-btn');
        const originalText = submitBtn.textContent;
        submitBtn.textContent = 'Envoi en cours...';
        submitBtn.disabled = true;

        // Simulate server delay
        setTimeout(function() {
            // Hide form and show thank you message
            contactForm.style.display = 'none';
            thankYouMessage.style.display = 'block';

            // Reset form for future submissions
            contactForm.reset();

            // Restore submit button text (in case user wants to resubmit)
            submitBtn.textContent = originalText;
            submitBtn.disabled = false;
        }, 1000);
    });

    // Smooth scrolling for navigation links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function(e) {
            e.preventDefault();
            const target = document.querySelector(this.getAttribute('href'));
            if (target) {
                target.scrollIntoView({
                    behavior: 'smooth',
                    block: 'start'
                });
            }
        });
    });
});
